-- DESCO / Flyway V2 : datos referenciales y seguridad (sin transacciones operativas).
-- INSERT idempotentes: compara PK y, cuando corresponde, clave natural.
-- IDs del snapshot se conservan para respetar referencias FK y jerarquias RBAC.
-- NO modifica valores de registros ya existentes. No inserta sesiones, OTP ni auditorias.
SET NOCOUNT ON;
GO

-- Durante la carga inicial se suspenden solo los triggers de tablas sembradas.
-- Los estados originales se restauran despues de los INSERT.
CREATE TABLE #DESCO_Flyway_TriggerState (
    schema_name sysname NOT NULL,
    table_name sysname NOT NULL,
    trigger_name sysname NOT NULL,
    was_disabled bit NOT NULL
);
INSERT INTO #DESCO_Flyway_TriggerState (schema_name, table_name, trigger_name, was_disabled)
SELECT s.name, t.name, tr.name, tr.is_disabled
FROM sys.triggers tr
JOIN sys.tables t ON tr.parent_id = t.object_id
JOIN sys.schemas s ON t.schema_id = s.schema_id
WHERE tr.parent_class = 1
  AND ((s.name = N'geo' AND t.name = N'Ubicacion') OR (s.name = N'logistica' AND t.name = N'Producto') OR (s.name = N'logistica' AND t.name = N'Suministro') OR (s.name = N'org' AND t.name = N'Area') OR (s.name = N'org' AND t.name = N'Asociacion') OR (s.name = N'org' AND t.name = N'EmpleadoArea') OR (s.name = N'org' AND t.name = N'Empleado') OR (s.name = N'org' AND t.name = N'Empresa') OR (s.name = N'org' AND t.name = N'Persona') OR (s.name = N'org' AND t.name = N'SocioAsociacion') OR (s.name = N'org' AND t.name = N'UOT') OR (s.name = N'seg' AND t.name = N'UsuarioCorreoSeguridad') OR (s.name = N'seg' AND t.name = N'UsuarioRol') OR (s.name = N'seg' AND t.name = N'Usuario'));
DISABLE TRIGGER ALL ON [geo].[Ubicacion];
DISABLE TRIGGER ALL ON [logistica].[Producto];
DISABLE TRIGGER ALL ON [logistica].[Suministro];
DISABLE TRIGGER ALL ON [org].[Area];
DISABLE TRIGGER ALL ON [org].[Asociacion];
DISABLE TRIGGER ALL ON [org].[EmpleadoArea];
DISABLE TRIGGER ALL ON [org].[Empleado];
DISABLE TRIGGER ALL ON [org].[Empresa];
DISABLE TRIGGER ALL ON [org].[Persona];
DISABLE TRIGGER ALL ON [org].[SocioAsociacion];
DISABLE TRIGGER ALL ON [org].[UOT];
DISABLE TRIGGER ALL ON [seg].[UsuarioCorreoSeguridad];
DISABLE TRIGGER ALL ON [seg].[UsuarioRol];
DISABLE TRIGGER ALL ON [seg].[Usuario];
GO


