-- Devolver al estado inicial los triggers activos; los que estaban deshabilitados siguen asi.
DECLARE @DescoRestoreTriggers NVARCHAR(MAX) = N'';
SELECT @DescoRestoreTriggers = @DescoRestoreTriggers
    + N'ENABLE TRIGGER ' + QUOTENAME(trigger_name)
    + N' ON ' + QUOTENAME(schema_name) + N'.' + QUOTENAME(table_name) + N';' + NCHAR(10)
FROM #DESCO_Flyway_TriggerState WHERE was_disabled = 0;
IF @DescoRestoreTriggers <> N'' EXEC sys.sp_executesql @DescoRestoreTriggers;
DROP TABLE #DESCO_Flyway_TriggerState;
GO
